INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('06c4fb53-4dc3-5b87-94c2-28e13dfedfb0','18135ac5-c260-5a37-b0c8-1f4ccf244cdc','82322f42-e27a-5c54-92e9-84cdf62617ed',1,'introduction','{"title":"Explore: People and things","text_en":"In this lesson, you will work with pronouns and basic nouns. This helps you communicate clearly in a practical situation.","text_vi":"Bài học này giúp bạn luyện pronouns and basic nouns trong ngữ cảnh thực tế."}'::jsonb) ON CONFLICT(id) DO NOTHING;
