INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('e5712187-4089-5b8d-b6be-b2d88f267123','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',1,'introduction','{"title":"Explore: Polite needs","text_en":"In this lesson, you will work with basic requests. This helps you communicate clearly in a practical situation.","text_vi":"Bài học này giúp bạn luyện basic requests trong ngữ cảnh thực tế."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('411825ef-5a7e-51af-8418-287b2d06fe2f','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',2,'objective','{"title":"Learning goal","text_en":"Understand the core language for basic requests","text_vi":"Hoàn thành mục tiêu và tự tạo một ví dụ mới."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('808f5f4a-aa5b-5584-8f69-8b4b8b69bee3','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',3,'theory','{"title":"can / could requests","text_en":"Focus on can / could requests. Notice the form, meaning, and position of each word before you produce your own sentence.","text_vi":"Tập trung vào cấu trúc can / could requests; quan sát dạng, nghĩa và vị trí từ."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('7d4970b2-01b0-594e-8494-e913fa8721c8','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',4,'vocabulary','{"word":"please","meaning_vi":"Từ/cụm từ trọng tâm về basic requests","part_of_speech":"word or phrase","example_en":"Use “please” when discussing basic requests.","example_vi":"Dùng “please” khi nói về basic requests."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('592f6a68-4eea-5feb-87fc-ceb0191d59bc','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',5,'vocabulary','{"word":"help","meaning_vi":"Từ/cụm từ trọng tâm về basic requests","part_of_speech":"word or phrase","example_en":"Use “help” when discussing basic requests.","example_vi":"Dùng “help” khi nói về basic requests."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('91ee2455-77ba-59c2-afda-38efda643890','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',6,'vocabulary','{"word":"need","meaning_vi":"Từ/cụm từ trọng tâm về basic requests","part_of_speech":"word or phrase","example_en":"Use “need” when discussing basic requests.","example_vi":"Dùng “need” khi nói về basic requests."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('c104e96f-f466-5110-9b65-3419366136f2','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',7,'example','{"title":"Natural examples","text_en":"Model: We use please in a sentence about basic requests. Vietnamese guide: Hãy chú ý ngữ cảnh và cấu trúc can / could requests. Then adapt the model with your own information.","text_vi":"Đọc ví dụ, xác định cấu trúc, rồi thay bằng thông tin của bạn."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('754b6e6b-72a4-5a11-b116-eda17c74ed4b','df7ac1e1-e8e2-51ab-847a-b24eb8af6182','5c9dce64-1684-505a-9c24-049f214f5e1b',8,'summary','{"title":"Lesson recap","text_en":"You practiced please, help, need and can / could requests. Use them together in one accurate, meaningful response.","text_vi":"Ôn từ vựng, cấu trúc và áp dụng trong một câu trả lời có nghĩa."}'::jsonb) ON CONFLICT(id) DO NOTHING;
