INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('84826f33-19ef-57b5-ae22-59e96a4bdb9a','75421af4-187f-547d-b6c6-af3cb91b0500','c74028f2-16f1-5e12-9b9c-5090008aa7f1',1,'introduction','{"title":"Explore: Make a plan","text_en":"In this lesson, you will work with arrangements and suggestions. This helps you communicate clearly in a practical situation.","text_vi":"Bài học này giúp bạn luyện arrangements and suggestions trong ngữ cảnh thực tế."}'::jsonb) ON CONFLICT(id) DO NOTHING;
