INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('453a2f84-f548-5eac-b623-bcb10356c2a9','75421af4-187f-547d-b6c6-af3cb91b0500','c74028f2-16f1-5e12-9b9c-5090008aa7f1',5,'vocabulary','{"word":"arrange","meaning_vi":"Từ/cụm từ trọng tâm về arrangements and suggestions","part_of_speech":"word or phrase","example_en":"Use “arrange” when discussing arrangements and suggestions.","example_vi":"Dùng “arrange” khi nói về arrangements and suggestions."}'::jsonb) ON CONFLICT(id) DO NOTHING;
