INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('f2e2ef1f-d0dd-5d85-8b70-4aca06f913ae','75421af4-187f-547d-b6c6-af3cb91b0500','c74028f2-16f1-5e12-9b9c-5090008aa7f1',7,'example','{"title":"Natural examples","text_en":"Model: We use available in a sentence about arrangements and suggestions. Vietnamese guide: Hãy chú ý ngữ cảnh và cấu trúc could / should / let''s. Then adapt the model with your own information.","text_vi":"Đọc ví dụ, xác định cấu trúc, rồi thay bằng thông tin của bạn."}'::jsonb) ON CONFLICT(id) DO NOTHING;
