INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('fe150724-0047-5200-99e2-f690c6215d92','30bcc966-0c40-54ca-95a4-c77ecf1c3ca7','97e6af3b-6935-57cf-965c-cd86bb481b49',1,'introduction','{"title":"Explore: Express nuance","text_en":"In this lesson, you will work with complex sentence structures. This helps you communicate clearly in a practical situation.","text_vi":"Bài học này giúp bạn luyện complex sentence structures trong ngữ cảnh thực tế."}'::jsonb) ON CONFLICT(id) DO NOTHING;
