INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('868e3481-85c6-5f0a-b3f6-1c103142ba22','30bcc966-0c40-54ca-95a4-c77ecf1c3ca7','97e6af3b-6935-57cf-965c-cd86bb481b49',3,'theory','{"title":"subordination and emphasis","text_en":"Focus on subordination and emphasis. Notice the form, meaning, and position of each word before you produce your own sentence.","text_vi":"Tập trung vào cấu trúc subordination and emphasis; quan sát dạng, nghĩa và vị trí từ."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('59e27a10-b8b5-56ef-87cf-cdb729cc30d0','30bcc966-0c40-54ca-95a4-c77ecf1c3ca7','97e6af3b-6935-57cf-965c-cd86bb481b49',4,'vocabulary','{"word":"extent","meaning_vi":"Từ/cụm từ trọng tâm về complex sentence structures","part_of_speech":"word or phrase","example_en":"Use “extent” when discussing complex sentence structures.","example_vi":"Dùng “extent” khi nói về complex sentence structures."}'::jsonb) ON CONFLICT(id) DO NOTHING;
