INSERT INTO public.journey_lesson_revisions(id,lesson_id,version,status,source,content_hash,published_at) VALUES ('8c458117-f987-5293-92e3-815352346967','1b715125-8aa8-5338-b0de-e3fb59a26671',1,'published','curated','311224fcf5959892d5e67658632aa8119e0958cfdced3f84dd1099b8c7b0f380',transaction_timestamp()) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('bf801de5-a00b-57e6-bebf-c83bd56b9ba6','8c458117-f987-5293-92e3-815352346967','1b715125-8aa8-5338-b0de-e3fb59a26671',1,'introduction','{"title":"Capstone scenario","text_en":"You are preparing a proposal for an international team. Read the situation, evaluate the evidence, and select language that is clear, professional, and appropriately nuanced.","text_vi":"Bạn chuẩn bị đề xuất cho một nhóm quốc tế; cần tổng hợp thông tin và chọn ngôn ngữ phù hợp."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('4f518e2f-5911-5be3-afac-1351610e9b83','8c458117-f987-5293-92e3-815352346967','1b715125-8aa8-5338-b0de-e3fb59a26671',2,'theory','{"title":"Integrated strategy","text_en":"First identify purpose and audience. Next compare sources, state a supported position, anticipate a concern, and end with a practical action.","text_vi":"Xác định mục đích và người đọc, so sánh nguồn, nêu quan điểm có căn cứ và đề xuất hành động."}'::jsonb) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.journey_lesson_blocks(id,revision_id,lesson_id,position,block_type,content) VALUES ('5fa0c5a4-6610-59ae-9bad-78c3c7071854','8c458117-f987-5293-92e3-815352346967','1b715125-8aa8-5338-b0de-e3fb59a26671',3,'summary','{"title":"Final reflection","text_en":"Review which reading, vocabulary, grammar, and communication strategies helped you most. Use the Smart Review path for remaining weaknesses.","text_vi":"Tự đánh giá điểm mạnh, điểm cần ôn và tiếp tục bằng Smart Review."}'::jsonb) ON CONFLICT(id) DO NOTHING;
